const body = ($input.first().json.body || $input.first().json);
return [{ json: {
  user_id: body.user_id || 'demo-user',
  role: body.role || 'Senior ML Engineer',
  location: body.location || 'New York, United States',
  keywords: body.keywords || ['Python', 'LLM', 'AI', 'n8n'],
  remote: true,
  demo_mode: body.demo_mode !== false,
  digest_date: new Date().toLocaleDateString('en-US', { weekday: 'long', month: 'long', day: 'numeric' }),
  session_id: `digest_${Date.now()}`
}}];

const result = $input.first().json;
const prefs = $('\ud83d\udccb Load User Preferences').first().json;

const data = result.data || result;
const topJobs = (data.top_jobs || data.scored_jobs || []).slice(0, 3);
const marketIntel = data.market_intel || {};

if (topJobs.length === 0) {
  return [{ json: { has_jobs: false, message: 'No new high-fit jobs found today. Check back tomorrow!', digest_date: prefs.digest_date } }];
}

return [{ json: {
  has_jobs: true,
  top_jobs: topJobs,
  jobs_found: data.jobs_found || topJobs.length,
  high_fit_count: data.high_fit_jobs || topJobs.length,
  market_intel: marketIntel,
  digest_date: prefs.digest_date,
  user_id: prefs.user_id,
  session_id: prefs.session_id
}}];

const d = $input.first().json;
const jobs = d.top_jobs || [];
const intel = d.market_intel || {};

const rankEmojis = ['1\ufe0f\u20e3', '2\ufe0f\u20e3', '3\ufe0f\u20e3'];
const scoreStars = (score) => {
  if (score >= 9) return '\u2b50\u2b50\u2b50\u2b50\u2b50';
  if (score >= 8) return '\u2b50\u2b50\u2b50\u2b50';
  if (score >= 7) return '\u2b50\u2b50\u2b50';
  return '\u2b50\u2b50';
};

const jobLines = jobs.map((j, i) => {
  const remoteTag = j.remote !== false ? '\ud83c\udfe0 Remote' : '\ud83c\udfd9\ufe0f Onsite';
  const salary = j.salary || j.salary_estimate || 'Salary not listed';
  return `${rankEmojis[i]} *${j.title}* @ ${j.company}\n   ${scoreStars(j.fit_score)} Fit: ${j.fit_score}/10\n   \ud83d\udcb0 ${salary} | ${remoteTag}\n   \ud83d\udca1 ${j.fit_reason || 'Strong match'}`;
}).join('\n\n');

const marketLine = intel.market_summary
  ? `\n\n\ud83d\udcca *Market Pulse:* ${intel.market_summary.slice(0, 120)}...`
  : '';

const avgSalary = intel.avg_salary_range ? `\n\ud83d\udcb5 Avg salary: ${intel.avg_salary_range}` : '';
const competition = intel.competition_level ? `\n\u2694\ufe0f Competition: ${intel.competition_level}` : '';

const message = `\ud83c\udf05 *CareerForge Morning Digest*\n${d.digest_date}\n\n\ud83d\udd25 *${d.high_fit_count} new high-fit jobs found!*\n\n${jobLines}${marketLine}${avgSalary}${competition}\n\n\u2014\n_Powered by CareerForge \u00d7 n8n_`;

return [{ json: { message, session_id: d.session_id, user_id: d.user_id } }];

const d = $input.first().json;
return [{ json: { message: `☀️ *CareerForge Morning Digest*
${d.digest_date}

✅ No new high-fit jobs today.

The market is quiet — check back tomorrow!

_Powered by CareerForge × n8n_` } }];

const d = $input.first().json;
return [{ json: {
  status: 'digest_sent',
  channel: 'telegram',
  message_preview: d.message?.slice(0, 100) + '...',
  sent_at: new Date().toISOString()
}}];
